      tone: { wave: "square", cut: 1800, q: 2.0, atk: .003, rel: .5, gain: .28, verb: .25 },
      words: ["the piano loop, dark and minor", "the sub, sliding under it"],
      word: v => (v === 0 ? [only("gate", rotate(5))] : [drop(3)]),
