      parents: { troubadour: 0.55, polychoral: 0.45 }, wants: [], near: "crooner",
      instr: ["solo_vox", "harpsichord"],
      entry: v => (v === 0 ? 2 : 0), reg: v => (v === 0 ? 0 : -1),
