      mode: MODES.melodic, scale: DIATONIC,
      artic: "legato", maxHold: 6, incClamp: 2,
      tone: { wave: "triangle", cut: 2600, q: 0.8, atk: .01, rel: 2.0, gain: .26, verb: .5 },
      words: ["the song, up high, taking its time", "the left hand, wide and low"],
      word: v => (v === 1 ? [drop(2)] : []),
