      instr: ["solo_vox", "clean_guitar", "brass_section"],
      drumkit: "acoustic",
      entry: v => v, reg: v => (v === 2 ? -1 : 0), realize: () => "line",
      part: ["lead", "riff", "counter"],
      roots: [0, 3, 4, 0], mode: MODES.ionian, scale: SCALES.majpent,
